import React, { useState, useEffect } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { getCart, updateCartItem, removeCartItem, clearCart } from '../services/api';
import { isAuthenticated } from '../util/auth';
import { useTheme } from '../context/ThemeContext';
import Toast from '../components/Toast';
import useToast from '../hooks/useToast';

const Cart = ({ cartCount }) => {
  const [cart, setCart] = useState(null);
  const [loading, setLoading] = useState(true);
  const navigate = useNavigate();
  const { isDarkMode } = useTheme();
  const { showInfoToast, toasts, removeToast } = useToast();

  // Get gradient colors for fallback background
  const getCategoryGradient = (category) => {
    const gradients = {
      milk: 'from-blue-200 to-blue-400 dark:from-blue-800 dark:to-blue-600',
      ghee: 'from-amber-200 to-amber-400 dark:from-amber-800 dark:to-amber-600',
      cheese: 'from-yellow-200 to-yellow-400 dark:from-yellow-800 dark:to-yellow-600',
      butter: 'from-orange-200 to-orange-400 dark:from-orange-800 dark:to-orange-600',
      paneer: 'from-purple-200 to-purple-400 dark:from-purple-800 dark:to-purple-600',
      lassi: 'from-pink-200 to-pink-400 dark:from-pink-800 dark:to-pink-600',
      yogurt: 'from-green-200 to-green-400 dark:from-green-800 dark:to-green-600',
      curd: 'from-red-200 to-red-400 dark:from-red-800 dark:to-red-600',
      cream: 'from-indigo-200 to-indigo-400 dark:from-indigo-800 dark:to-indigo-600',
      buttermilk: 'from-cyan-200 to-cyan-400 dark:from-cyan-800 dark:to-cyan-600'
    };
    return gradients[category] || 'from-gray-200 to-gray-400 dark:from-gray-800 dark:to-gray-600';
  };

  // Get emoji for category
  const getCategoryEmoji = (category) => {
    const emojis = {
      milk: '🥛',
      ghee: '🥇',
      cheese: '🧀',
      butter: '🧈',
      paneer: '🧊',
      lassi: '🥤',
      yogurt: '🥣',
      curd: '🥄',
      cream: '🍦',
      buttermilk: '🥛'
    };
    return emojis[category] || '🥛';
  };

  useEffect(() => {
    const checkAuthAndFetchCart = () => {
      if (isAuthenticated()) {
        fetchCart();
      } else {
        setCart(null);
        setLoading(false);
      }
    };

    checkAuthAndFetchCart();

    // Add event listener for storage changes (when login happens in another tab)
    const handleStorageChange = (e) => {
      if (e.key === 'token' || e.key === 'user') {
        checkAuthAndFetchCart();
      }
    };

    window.addEventListener('storage', handleStorageChange);

    return () => {
      window.removeEventListener('storage', handleStorageChange);
    };
  }, []);

  const fetchCart = async () => {
    try {
      setLoading(true);
      const res = await getCart();
      setCart(res.data);
    } catch (error) {
      console.error('Error fetching cart:', error);
    } finally {
      setLoading(false);
    }
  };

  const handleQuantityChange = async (itemId, newQuantity) => {
    try {
      if (newQuantity < 1) {
        await handleRemoveItem(itemId);
      } else {
        const res = await updateCartItem(itemId, newQuantity);
        setCart(res.data);
        if (cartCount) cartCount(res.data.totalItems);
      }
    } catch (error) {
      alert(error.response?.data?.message || 'Error updating quantity');
    }
  };

  const handleRemoveItem = async (itemId) => {
    try {
      const res = await removeCartItem(itemId);
      setCart(res.data);
      if (cartCount) cartCount(res.data.totalItems);
    } catch (error) {
      alert(error.response?.data?.message || 'Error removing item');
    }
  };

  const handleClearCart = async () => {
    if (!window.confirm('Are you sure you want to clear your cart?')) return;
    
    try {
      await clearCart();
      setCart({ items: [], totalPrice: 0, totalItems: 0 });
      if (cartCount) cartCount(0);
    } catch (error) {
      alert(error.response?.data?.message || 'Error clearing cart');
    }
  };

  const handleCheckout = () => {
    if (!isAuthenticated()) {
      navigate('/login');
      return;
    }
    navigate('/checkout');
  };

  if (!isAuthenticated()) {
    return (
      <div className="fade-in min-h-screen bg-gradient-to-br from-gray-50 to-gray-100 dark:from-gray-900 dark:to-gray-800 flex items-center justify-center px-4">
        <div className={`text-center py-20 rounded-3xl ${isDarkMode ? 'bg-gray-800/50 backdrop-blur-xl border border-white/10' : 'bg-white/70 backdrop-blur-xl border border-gray-200'} shadow-xl max-w-md w-full`}>
          <div className="w-32 h-32 mx-auto mb-6 rounded-3xl bg-gradient-to-br from-blue-100 to-cyan-100 dark:from-blue-900/50 dark:to-cyan-900/50 flex items-center justify-center">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-16 w-16 text-blue-600 dark:text-blue-400" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M3 3h2l.4 2M7 13h10l4-8H5.4M7 13L5.4 5M7 13l-2.293 2.293c-.63.63-.184 1.707.707 1.707H17m0 0a2 2 0 100 4 2 2 0 000-4zm-8 2a2 2 0 11-4 0 2 2 0 014 0z" />
            </svg>
          </div>
          <h3 className={`text-2xl font-bold mb-3 ${isDarkMode ? 'text-white' : 'text-gray-800'}`}>
            Login Required
          </h3>
          <p className={`text-lg ${isDarkMode ? 'text-gray-400' : 'text-gray-600'} mb-6`}>
            Please login to view your cart
          </p>
          <div className="flex space-x-3">
            <Link 
              to="/login" 
              className="flex-1 px-6 py-3 bg-gradient-to-r from-primary-500 to-secondary-500 text-white rounded-xl font-medium hover:shadow-lg hover:shadow-primary-500/30 transform hover:scale-[1.02] transition-all duration-200"
            >
              Login
            </Link>
            <Link 
              to="/register" 
              className={`flex-1 px-6 py-3 rounded-xl font-medium transform hover:scale-[1.02] transition-all duration-200 ${
                isDarkMode 
                  ? 'bg-gray-700 text-gray-300 hover:bg-gray-600' 
                  : 'bg-gray-100 text-gray-700 hover:bg-gray-200'
              }`}
            >
              Create Account
            </Link>
          </div>
        </div>
      </div>
    );
  }

  if (loading) {
    return (
      <div className="fade-in min-h-screen bg-gradient-to-br from-gray-50 to-gray-100 dark:from-gray-900 dark:to-gray-800 flex items-center justify-center">
        <div className="relative">
          <div className="w-16 h-16 border-4 border-primary-200 border-t-primary-600 rounded-full animate-spin"></div>
          <div className="absolute inset-0 flex items-center justify-center">
            <div className="w-8 h-8 bg-gradient-to-br from-primary-500 to-secondary-500 rounded-full animate-pulse"></div>
          </div>
        </div>
      </div>
    );
  }

  if (!cart || cart.items.length === 0) {
    return (
      <div className="fade-in min-h-screen bg-gradient-to-br from-gray-50 to-gray-100 dark:from-gray-900 dark:to-gray-800 flex items-center justify-center px-4">
        <div className={`text-center py-20 rounded-3xl ${isDarkMode ? 'bg-gray-800/50 backdrop-blur-xl border border-white/10' : 'bg-white/70 backdrop-blur-xl border border-gray-200'} shadow-xl max-w-md w-full`}>
          <div className="w-32 h-32 mx-auto mb-6 rounded-3xl bg-gradient-to-br from-blue-100 to-cyan-100 dark:from-blue-900/50 dark:to-cyan-900/50 flex items-center justify-center">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-16 w-16 text-blue-600 dark:text-blue-400" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M3 3h2l.4 2M7 13h10l4-8H5.4M7 13L5.4 5M7 13l-2.293 2.293c-.63.63-.184 1.707.707 1.707H17m0 0a2 2 0 100 4 2 2 0 000-4zm-8 2a2 2 0 11-4 0 2 2 0 014 0z" />
            </svg>
          </div>
          <h3 className={`text-2xl font-bold mb-3 ${isDarkMode ? 'text-white' : 'text-gray-800'}`}>
            Your cart is empty
          </h3>
          <p className={`text-lg ${isDarkMode ? 'text-gray-400' : 'text-gray-600'} mb-6`}>
            Add some delicious dairy products!
          </p>
          <Link 
            to="/products" 
            className="px-6 py-3 bg-gradient-to-r from-primary-500 to-secondary-500 text-white rounded-xl font-medium hover:shadow-lg hover:shadow-primary-500/30 transform hover:scale-[1.02] transition-all duration-200"
          >
            Browse Products
          </Link>
        </div>
      </div>
    );
  }

  return (
    <div className="fade-in min-h-screen bg-gradient-to-br from-gray-50 to-gray-100 dark:from-gray-900 dark:to-gray-800">
      <div className="max-w-7xl mx-auto px-4 py-8">
        {/* Modern Header */}
        <div className="text-center mb-12">
          <div className="inline-block relative group">
            <h1 className={`text-4xl md:text-5xl font-bold mb-4 ${isDarkMode ? 'text-white' : 'text-gray-800'}`}>
              <span className="bg-gradient-to-r from-primary-600 via-secondary-600 to-primary-600 bg-clip-text text-transparent">
                Shopping Cart
              </span>
            </h1>
            {/* Animated Underline */}
            <div className="absolute -bottom-1 left-0 w-full h-1 bg-gradient-to-r from-primary-500 to-secondary-500 rounded-full transform scale-x-0 group-hover:scale-x-100 transition-transform duration-500"></div>
          </div>
          <p className={`text-lg ${isDarkMode ? 'text-gray-300' : 'text-gray-600'} mb-4`}>
            Review your delicious dairy products
          </p>
          <div className={`inline-flex items-center px-4 py-2 rounded-full ${isDarkMode ? 'bg-gray-800 text-gray-300' : 'bg-white text-gray-600'} shadow-lg`}>
            <svg className="w-5 h-5 mr-2" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 3h2l.4 2M7 13h10l4-8H5.4M7 13L5.4 5M7 13l-2.293 2.293c-.63.63-.184 1.707.707 1.707H17m0 0a2 2 0 100 4 2 2 0 000-4zm-8 2a2 2 0 11-4 0 2 2 0 014 0z" />
            </svg>
            {cart.totalItems} Items in Cart
          </div>
        </div>

        <div className="grid lg:grid-cols-3 gap-8">
          {/* Cart Items */}
          <div className="lg:col-span-2 space-y-4">
            {cart.items.map((item) => (
              <div key={item._id} className={`group relative overflow-hidden transition-all duration-700 hover:shadow-4xl hover:shadow-primary-500/20 transform hover:scale-[1.02] rounded-2xl border-2 border-gray-200/50 dark:border-gray-700/50 hover:border-primary-500/50 bg-gradient-to-br from-white via-gray-50 to-gray-100 dark:from-gray-800 dark:via-gray-900 dark:to-black backdrop-blur-xl`}>
                <div className="p-6">
                  <div className="flex items-center space-x-4">
                    {/* Item Image */}
                    <div className="relative w-24 h-24 rounded-xl overflow-hidden flex-shrink-0">
                      {/* Animated Background Gradient */}
                      <div className="absolute inset-0 bg-gradient-to-br from-primary-500/10 via-transparent to-secondary-500/10 opacity-0 group-hover:opacity-100 transition-opacity duration-1000"></div>
                      
                      {(item.product?.image && item.product.image !== '') ? (
                        <img 
                          src={item.product.image} 
                          alt={item.product?.name || item.name} 
                          className="w-full h-full object-cover transition-transform duration-1000 group-hover:scale-110" 
                          onError={(e) => {
                            e.target.style.display = 'none';
                            e.target.nextSibling.style.display = 'flex';
                          }}
                        />
                      ) : null}
                      <div 
                        className={`w-full h-full flex items-center justify-center bg-gradient-to-br ${getCategoryGradient(item.product?.category)} ${item.product?.image ? 'hidden' : 'flex'}`}
                      >
                        <span className="text-6xl transform transition-all duration-700 group-hover:scale-110 group-hover:rotate-12">{getCategoryEmoji(item.product?.category)}</span>
                      </div>
                    </div>

                    {/* Item Details */}
                    <div className="flex-1">
                      <h3 className={`font-bold text-lg mb-1 capitalize transition-all duration-300 group-hover:text-primary-600 dark:group-hover:text-primary-400 ${isDarkMode ? 'text-gray-100' : 'text-gray-800'}`}>
                        {item.product?.name || item.name}
                      </h3>
                      <p className={`text-sm ${isDarkMode ? 'text-gray-400' : 'text-gray-600'} mb-3`}>
                        ₹{item.product?.price || item.price}/{item.product?.unit || item.unit}
                      </p>
                      
                      {/* Quantity Selector */}
                      <div className="flex items-center space-x-3">
                        <div className={`flex items-center border-2 ${isDarkMode ? 'border-gray-600' : 'border-gray-300'} rounded-xl overflow-hidden shadow-sm backdrop-blur-sm ${isDarkMode ? 'bg-gray-800/50' : 'bg-white/50'}`}>
                          <button
                            onClick={() => handleQuantityChange(item._id, item.quantity - 1)}
                            className={`w-10 h-10 flex items-center justify-center ${isDarkMode ? 'text-gray-300 hover:bg-primary-500 hover:text-white' : 'text-gray-600 hover:bg-primary-500 hover:text-white'} transition-all duration-300 font-bold cursor-pointer`}
                          >
                            -
                          </button>
                          <span className={`w-12 text-center font-bold ${isDarkMode ? 'text-gray-200' : 'text-gray-800'}`}>{item.quantity}</span>
                          <button
                            onClick={() => handleQuantityChange(item._id, item.quantity + 1)}
                            className={`w-10 h-10 flex items-center justify-center ${isDarkMode ? 'text-gray-300 hover:bg-primary-500 hover:text-white' : 'text-gray-600 hover:bg-primary-500 hover:text-white'} transition-all duration-300 font-bold cursor-pointer`}
                          >
                            +
                          </button>
                        </div>
                        
                        {/* Item Total */}
                        <div className="flex-1 text-right">
                          <p className="text-2xl font-bold text-primary-600 dark:text-primary-400">
                            ₹{(item.product?.price || item.price) * item.quantity}
                          </p>
                        </div>
                      </div>
                    </div>

                    {/* Remove Button */}
                    <button
                      onClick={() => handleRemoveItem(item._id)}
                      className="w-10 h-10 rounded-full flex items-center justify-center shadow-lg backdrop-blur-sm transition-all duration-300 hover:scale-110 bg-red-500/90 text-white hover:bg-red-600 flex-shrink-0"
                      title="Remove from cart"
                    >
                      <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" />
                      </svg>
                    </button>
                  </div>
                </div>
              </div>
            ))}
          </div>

          {/* Cart Summary */}
          <div className="lg:col-span-1">
            <div className={`relative p-6 rounded-3xl ${isDarkMode ? 'bg-gray-800/50 backdrop-blur-xl border border-white/10' : 'bg-white/70 backdrop-blur-xl border border-gray-200'} shadow-xl sticky top-8`}>
              <h3 className={`text-xl font-bold mb-6 ${isDarkMode ? 'text-white' : 'text-gray-800'}`}>
                Order Summary
              </h3>
              
              <div className="space-y-4 mb-6">
                <div className={`flex justify-between items-center pb-3 border-b ${isDarkMode ? 'border-gray-700' : 'border-gray-200'}`}>
                  <span className={`${isDarkMode ? 'text-gray-400' : 'text-gray-600'}`}>Items ({cart.totalItems})</span>
                  <span className={`text-lg font-bold ${isDarkMode ? 'text-gray-200' : 'text-gray-800'}`}>₹{cart.totalPrice}</span>
                </div>
                <div className="flex justify-between items-center">
                  <span className={`${isDarkMode ? 'text-gray-400' : 'text-gray-600'}`}>Delivery</span>
                  <span className="text-green-600 font-bold">Free</span>
                </div>
                <div className={`h-px ${isDarkMode ? 'bg-gray-700' : 'bg-gray-200'} my-4`}></div>
                <div className="flex justify-between items-center">
                  <span className={`text-xl font-bold ${isDarkMode ? 'text-gray-200' : 'text-gray-800'}`}>Total</span>
                  <span className="text-2xl font-bold text-primary-600 dark:text-primary-400">₹{cart.totalPrice}</span>
                </div>
              </div>

              {/* Clear Cart Button */}
              <button
                onClick={handleClearCart}
                className={`w-full py-3 rounded-xl font-medium transform hover:scale-[1.02] transition-all duration-200 mb-3 ${
                  isDarkMode 
                    ? 'bg-gray-700 text-gray-300 hover:bg-gray-600' 
                    : 'bg-gray-100 text-gray-700 hover:bg-gray-200'
                }`}
              >
                Clear Cart
              </button>

              {/* Checkout Button */}
              <button
                onClick={handleCheckout}
                className="w-full py-3 bg-gradient-to-r from-primary-500 to-secondary-500 text-white rounded-xl font-bold hover:from-primary-600 hover:to-secondary-600 transform hover:scale-[1.02] transition-all duration-200 shadow-lg hover:shadow-xl hover:shadow-primary-500/30"
              >
                Proceed to Checkout
              </button>
            </div>
          </div>
        </div>
      </div>

      {/* Toast Container */}
      {toasts.map(toast => (
        <Toast
          key={toast.id}
          message={toast.message}
          type={toast.type}
          duration={toast.duration}
          onClose={() => removeToast(toast.id)}
        />
      ))}
    </div>
  );
};

export default Cart;
